<?php
require __DIR__.'/bootstrap.php';$pdo=db();$err='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$act=$_POST['action']??'';if($act==='logout'){unset($_SESSION['user_id']);session_regenerate_id(true);header('Location: account.php');exit;}if($act==='register'){$name=trim((string)($_POST['name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');if(strlen($name)<2||strlen($name)>80||!$email||strlen($pass)<10)$err='Заполните имя, корректный email и пароль от 10 символов.';else try{$q=$pdo->prepare('INSERT INTO users(email,full_name,password_hash) VALUES(?,?,?)');$q->execute([$email,$name,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=(int)$pdo->lastInsertId();session_regenerate_id(true);header('Location: account.php');exit;}catch(Throwable $e){$err='Этот email уже зарегистрирован.';}}elseif($act==='login'){$q=$pdo->prepare('SELECT id,password_hash FROM users WHERE email=?');$q->execute([trim((string)($_POST['email']??''))]);$u=$q->fetch();if($u&&password_verify((string)($_POST['password']??''),$u['password_hash'])){$_SESSION['user_id']=(int)$u['id'];session_regenerate_id(true);header('Location: account.php');exit;}$err='Неверный email или пароль.';}}
$user=null;$orders=[];$bookings=[];if(!empty($_SESSION['user_id'])){$q=$pdo->prepare('SELECT full_name,email,created_at FROM users WHERE id=?');$q->execute([$_SESSION['user_id']]);$user=$q->fetch();$q=$pdo->prepare('SELECT id,total,status,created_at FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 50');$q->execute([$_SESSION['user_id']]);$orders=$q->fetchAll();$q=$pdo->prepare('SELECT booking_date,booking_time,guest_count,status FROM bookings WHERE user_id=? ORDER BY booking_date DESC LIMIT 50');$q->execute([$_SESSION['user_id']]);$bookings=$q->fetchAll();}page_start('Личный кабинет — Tokyo Premium','Ваши заказы и бронирования Tokyo Premium.');header_html();?><main class="admin-shell"><section class="admin-card"><div class="kicker">Tokyo Premium</div><?php if(!$user): ?><h1>Личный кабинет</h1><p>Сохраняйте историю заказов и бронирований в одном месте.</p><?php if($err):?><p class="form-status error"><?=e($err)?></p><?php endif ?><div class="intro-grid"><form method="post" class="admin-form"><h2>Войти</h2><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="login"><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Пароль<input type="password" name="password" required autocomplete="current-password"></label><button class="button">Войти</button></form><form method="post" class="admin-form"><h2>Создать аккаунт</h2><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="register"><label>Имя<input name="name" required minlength="2" maxlength="80" autocomplete="name"></label><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Пароль от 10 символов<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><button class="button">Регистрация</button></form></div><?php else: ?><div class="section-head"><div><h1>Здравствуйте, <?=e($user['full_name'])?></h1><p><?=e($user['email'])?></p></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="logout"><button class="button secondary">Выйти</button></form></div><h2>История заказов</h2><?php if(!$orders):?><p>Заказы, оформленные после входа в аккаунт, появятся здесь.</p><?php else:?><table class="admin-table"><thead><tr><th>Заказ</th><th>Сумма</th><th>Статус</th><th>Дата</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=number_format((int)$o['total'],0,'.',' ')?> ₸</td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach?></tbody></table><?php endif ?><h2>Бронирования</h2><?php if(!$bookings):?><p>Ваши бронирования появятся здесь.</p><?php else:?><table class="admin-table"><thead><tr><th>Дата</th><th>Время</th><th>Гостей</th><th>Статус</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><?=e($b['booking_date'])?></td><td><?=e($b['booking_time'])?></td><td><?=$b['guest_count']?></td><td><?=e($b['status'])?></td></tr><?php endforeach?></tbody></table><?php endif ?><?php endif ?></section></main><?php footer_html(); ?>